cat > schema.cypher <<'CYPHER'
CREATE GRAPH TYPE team {
  (person:Person => {name :: STRING NOT NULL IS KEY, role :: STRING}),
  (project:Project => {name :: STRING NOT NULL IS KEY, language :: STRING}),
  (issue:Issue => {id :: INTEGER NOT NULL IS KEY, title :: STRING, opened :: DATE, labels :: LIST<STRING NOT NULL>}),
  (person)-[:WORKS_ON => {since :: INTEGER}]->(project),
  (person)-[:MAINTAINS =>]->(project),
  (person)-[:KNOWS =>]->(person),
  (issue)-[:FILED_IN =>]->(project)
};
ALTER CURRENT GRAPH TYPE SET GRAPH TYPE team;
CYPHER
relate query --database ./team.rl < schema.cypher

guides/migrate/from-sqlite.mdx.command:
sqlite3 team.db <<'SQL'
CREATE TABLE people (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  role TEXT NOT NULL
);
CREATE TABLE projects (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  language TEXT,
  maintainer_id INTEGER REFERENCES people(id)
);
CREATE TABLE works_on (
  person_id INTEGER NOT NULL REFERENCES people(id),
  project_id INTEGER NOT NULL REFERENCES projects(id),
  since INTEGER NOT NULL,
  PRIMARY KEY (person_id, project_id)
);
CREATE TABLE knows (
  person_id INTEGER NOT NULL REFERENCES people(id),
  other_id INTEGER NOT NULL REFERENCES people(id),
  PRIMARY KEY (person_id, other_id)
);
CREATE TABLE issues (
  id INTEGER PRIMARY KEY,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  opened TEXT NOT NULL,
